//! Refresh of unedited seeded files and the bundle provenance line (#10571).
//!
//! Why: `tm fleet init` never overwrites an edited seed, so an existing
//! Architect kept every old script forever. It must receive updated scripts
//! it never edited, keep the ones its owner edited, and say which content the
//! bundle came from.
//! What: [`shipped_before`] answers whether bytes on disk are an earlier
//! shipped version of a destination, from `seed_history.tsv` (generated by
//! `scripts/architect_bundle_meta.py history`, the same shipped-history
//! pattern `architect_skills` uses for skills). [`provenance_line`] renders
//! the seeded `docs/architect/bundle-provenance.json` as one report line.
//! Test: `a_refresh_updates_an_unedited_earlier_copy`,
//! `a_refresh_keeps_an_edited_copy_and_reports_it`,
//! `every_embedded_seed_is_in_the_shipped_history`,
//! `init_and_status_report_the_bundle_provenance`.

use sha2::{Digest, Sha256};

/// Every byte-version `tm fleet init` has shipped, one `DEST<TAB>SHA256` per line.
const HISTORY: &str = include_str!("seed_history.tsv");

/// Where the provenance stamp is seeded, below the Architect directory.
pub(crate) const PROVENANCE_DEST: &str = "docs/architect/bundle-provenance.json";

/// Lowercase sha256 hex of `bytes`.
pub(crate) fn sha256_hex(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

/// The `(dest, sha256)` rows of the shipped history; comments and blanks skipped.
pub(crate) fn history() -> impl Iterator<Item = (&'static str, &'static str)> {
    HISTORY
        .lines()
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .filter_map(|l| l.split_once('\t'))
}

/// Whether `bytes` are a version of `dest` that tm shipped before.
///
/// Why: a live file equal to an earlier shipped copy was never edited, so
/// replacing it loses nothing; any other bytes are an edit and are kept.
/// What: sha256 of `bytes` against the history rows for `dest`.
/// Test: `a_refresh_updates_an_unedited_earlier_copy`.
pub(crate) fn shipped_before(dest: &str, bytes: &[u8]) -> bool {
    let hash = sha256_hex(bytes);
    history().any(|(d, h)| d == dest && h == hash)
}

/// One line naming the bundle's prototype commit, export manifest and file count.
///
/// Why: an install must say which prototype commit and content it runs.
/// What: parses the provenance JSON; `None` when it is not the schema-1 shape.
/// Test: `init_and_status_report_the_bundle_provenance`.
pub(crate) fn provenance_line(text: &str) -> Option<String> {
    let v: serde_json::Value = serde_json::from_str(text).ok()?;
    if v.get("schema")?.as_u64()? != 1 {
        return None;
    }
    let commit = v.get("prototype_commit")?.as_str()?;
    let manifest = v.get("export_manifest_sha256")?.as_str()?;
    let files = v.get("files")?.as_object()?.len();
    Some(format!(
        "bundle: prototype {commit}, export manifest sha256 {}, {files} files",
        manifest.get(..12).unwrap_or(manifest)
    ))
}
